import ast, base64, json, pathlib, zipfile, zlib
import xml.etree.ElementTree as ET
ROOT = pathlib.Path(__file__).resolve().parents[1]
PAYLOAD = ''
for spec in json.loads(zlib.decompress(base64.b64decode(PAYLOAD))):
    addon, version = spec['addon'], spec['version']
    patch = dict(spec['patch'])
    folder = ROOT / 'zips' / addon
    base = folder / (addon + '-' + spec['oldver'] + '.zip')
    out = folder / (addon + '-' + version + '.zip')
    with zipfile.ZipFile(base) as old, zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED) as new:
        for item in old.infolist():
            text = patch.pop(item.filename, None)
            new.writestr(item, text.encode() if text is not None else old.read(item.filename))
        for name, text in patch.items():
            new.writestr(name, text.encode())
    with zipfile.ZipFile(out) as z:
        assert z.testzip() is None
        assert ET.fromstring(z.read(addon + '/addon.xml')).get('version') == version
        settings = ET.fromstring(z.read(addon + '/resources/settings.xml'))
        buffer = next(n for n in settings.iter('setting') if n.get('id') == 'playback.hls_prebuffer_mb')
        assert buffer.get('default') == '320' and buffer.get('range') == '16,16,512'
        (folder / 'changelog.txt').write_bytes(z.read(addon + '/changelog.txt'))
        for name in spec['patch']:
            if name.endswith('.py'):
                ast.parse(z.read(name))
        if addon == 'plugin.video.xship':
            assert "_XSHIP_CHANGELOG_BUILD = '" + version + "'" in z.read(addon + '/service.py').decode()
    if spec['sync']:
        for name, text in spec['patch'].items():
            dest = ROOT / 'addons' / name
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(text)
    print('Validated:', addon, version, 'default=320MB')
